const escapar = (t) =>
    String(t)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;");

/**
 * Items para searchable-select. `id` = codigo; se conservan descripcion y unidad
 * para autocompletar la fila al elegir.
 */
export function consumiblesItems() {
    return CONSUMIBLES.map((c) => ({
        id: String(c.codigo),
        label: `${c.codigo} · ${c.descripcion} (${c.unidad})`,
        codigo: String(c.codigo),
        descripcion: c.descripcion,
        unidad: c.unidad,
    }));
}

/** Opciones <option> por si prefieres un <select> nativo. */
export function opcionesConsumiblesHtml(placeholder = "Selecciona un consumible…") {
    const partes = [`<option value="">${escapar(placeholder)}</option>`];
    for (const c of CONSUMIBLES) {
        partes.push(
            `<option value="${escapar(c.codigo)}" data-descripcion="${escapar(c.descripcion)}" data-unidad="${escapar(c.unidad)}">` +
                `${escapar(`${c.codigo} · ${c.descripcion} (${c.unidad})`)}` +
                `</option>`
        );
    }
    return partes.join("");
}
